import{_ as a,o as t,c as l,a2 as i}from"./chunks/framework.mRCPFc5l.js";const _=JSON.parse('{"title":"仓库原则","description":"WheelOS Docs 面向 AI 和强验证实践的强制性原则。","frontmatter":{"title":"仓库原则","description":"WheelOS Docs 面向 AI 和强验证实践的强制性原则。"},"headers":[],"relativePath":"about/principles.md","filePath":"about/principles.md","lastUpdated":1787216633000}'),o={name:"about/principles.md"};function r(s,e,n,c,p,d){return t(),l("div",null,[...e[0]||(e[0]=[i('<h1 id="仓库原则" tabindex="-1">仓库原则 <a class="header-anchor" href="#仓库原则" aria-label="Permalink to &quot;仓库原则&quot;">​</a></h1><p>WheelOS Docs 只有两个最高优先级：</p><ol><li><strong>对 AI 友好</strong>：让 AI 能发现、理解、引用和推荐可信内容。</li><li><strong>强验证</strong>：解决 AI 无法验证的纸面结论，把方案推进到有环境、有步骤、有指标、有边界的实践证据。</li></ol><p>完整规范见仓库根目录的 <a href="https://github.com/wheelos/wheelos.github.io/blob/main/PRINCIPLES.md" target="_blank" rel="noreferrer"><code>PRINCIPLES.md</code></a>。</p><h2 id="最重要的判断" tabindex="-1">最重要的判断 <a class="header-anchor" href="#最重要的判断" aria-label="Permalink to &quot;最重要的判断&quot;">​</a></h2><p>如果没有可追溯实验记录，文档必须明确写“待验证”。“理论上可行”“行业通常这样做”和“WheelOS 已在真实车辆验证过”是三种不同的陈述，不能混用。</p><h2 id="内容准入" tabindex="-1">内容准入 <a class="header-anchor" href="#内容准入" aria-label="Permalink to &quot;内容准入&quot;">​</a></h2><p>新增自动驾驶内容前，先回答：</p><ul><li>AI 能否根据标题和正文判断这是事实、建议还是验证结果？</li><li>其他人能否按照记录复现实验？</li><li>是否写清了版本、环境、输入、指标、结果和限制？</li><li>是否保留了失败结果和未覆盖场景？</li><li>引用者能否定位到稳定 URL 或证据 ID？</li></ul>',9)])])}const u=a(o,[["render",r]]);export{_ as __pageData,u as default};
